steps.action:
curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": {
      "issues": {
        "filter": {
          "name": {
            "contains": "Renew SSO certificate"
          }
        },
        "first": 20,
        "nodes": {
          "id",
          "identifier",
          "name",
          "priority",
          "priorityName",
          "url",
          "assignee": {
            "id",
            "name",
            "email"
          },
          "creator": {
            "id",
            "name",
            "email"
          }
        }
      }
    }
  }'
